INSERT INTO `modules` (`module_id`, `class`, `name`, `valuable`) VALUES (NULL, 'City', 'Город', '1');CREATE TABLE IF NOT EXISTS `cities` (  `id` int(11) NOT NULL AUTO_INCREMENT,  `editor_id` int(11) NOT NULL,  `visible` tinyint(1) NOT NULL,  `position` int(11) NOT NULL,  `city_id` int(11) NOT NULL,  `delivery_methods` varchar(255) NOT NULL,  `payment_methods` varchar(255) NOT NULL,  `name` varchar(255) NOT NULL,  `url` varchar(255) NOT NULL,  `image` varchar(255) NOT NULL,  `meta_title` varchar(255) NOT NULL,  `meta_keywords` varchar(255) NOT NULL,  `meta_description` varchar(255) NOT NULL,  `text` text NOT NULL,  `text2` text NOT NULL,  `delivery_ids` varchar(255) NOT NULL,  `payment_ids` varchar(255) NOT NULL,  `map_url` varchar(512) NOT NULL,  `lastmod` datetime NOT NULL,  PRIMARY KEY (`id`)) ENGINE=MyISAM  DEFAULT CHARSET=utf8 AUTO_INCREMENT=1 ;